import os
import socket
import subprocess
import sys
import time
from pathlib import Path

import httpx
import pytest

from tests.support.api import BookshelfApi
from tests.support.data import TEST_PASSWORD, unique

ROOT = Path(__file__).resolve().parents[1]


def pytest_collection_modifyitems(items):
    # tests/api/* get the "api" marker, tests/ui/* get "ui", so `pytest -m ui` works.
    for item in items:
        folder = item.path.parent.name
        if folder in ("api", "ui"):
            item.add_marker(folder)


def _free_port() -> int:
    with socket.socket() as s:
        s.bind(("127.0.0.1", 0))
        return s.getsockname()[1]


def _wait_until_up(url: str, proc: subprocess.Popen, timeout: float = 20) -> None:
    deadline = time.monotonic() + timeout
    while time.monotonic() < deadline:
        if proc.poll() is not None:
            raise RuntimeError(f"App exited early with code {proc.returncode}")
        try:
            if httpx.get(f"{url}/health", timeout=1).status_code == 200:
                return
        except httpx.TransportError:
            pass
        time.sleep(0.2)
    raise RuntimeError(f"App did not start within {timeout}s")


@pytest.fixture(scope="session")
def base_url(tmp_path_factory):
    """Starts a fresh app with an empty database for this test session (one per
    xdist worker). Set BASE_URL to test an already running app instead, or
    APP_DB_PATH to choose where the app keeps its database."""
    external = os.environ.get("BASE_URL")
    if external:
        yield external.rstrip("/")
        return

    port = _free_port()
    db_path = os.environ.get("APP_DB_PATH") or str(tmp_path_factory.mktemp("db") / "bookshelf.db")
    env = {**os.environ, "DB_PATH": db_path}
    proc = subprocess.Popen(
        [sys.executable, "-m", "uvicorn", "app.main:app", "--port", str(port), "--log-level", "warning"],
        cwd=ROOT,
        env=env,
    )
    url = f"http://127.0.0.1:{port}"
    try:
        _wait_until_up(url, proc)
        yield url
    finally:
        proc.terminate()
        proc.wait(timeout=10)


